import multiprocessing as mp
import os
import random
import sys
import tempfile

sys.path.insert(0, "/mnt/c/Users/SL Chen/Desktop/cc_task/cla04/A/task009")
from weighted_batcher import append_metrics, compact_metrics, recover_metrics, rotate_metrics


def writer(wid, path, n, outq):
    accepted = []
    for i in range(n):
        try:
            append_metrics(path, '{"w":%d,"i":%d}' % (wid, i))
            accepted.append((wid, i))
        except OSError as e:
            print("append error", e)
        # tiny pause so operations interleave
        if random.random() < 0.02:
            for _ in range(1000):
                pass
    outq.put(accepted)


def rotator(path, stop_after):
    for _ in range(stop_after):
        try:
            rotate_metrics(path)
        except FileNotFoundError:
            # live log can vanish in the rename/recreate window
            pass


def compactor(path, stop_after):
    for _ in range(stop_after):
        try:
            compact_metrics(path)
        except FileNotFoundError:
            pass


def reader(path, stop_event, errors):
    try:
        while not stop_event.is_set():
            seen = []
            for r in recover_metrics(path):
                seen.append((r["w"], r["i"]))
            # no duplicate records in any observed snapshot
            if len(seen) != len(set(seen)):
                errors.put("duplicate in snapshot")
    except (OSError, ValueError) as e:
        errors.put(f"snapshot error: {e!r}")


def trial(trial_id):
    tmpd = tempfile.mkdtemp()
    path = os.path.join(tmpd, "m.log")
    open(path, "wb").close()
    n_writers, per = 4, 60
    q = mp.Queue()
    errq = mp.Queue()
    stop = mp.Event()
    procs = [mp.Process(target=writer, args=(w, path, per, q))
             for w in range(n_writers)]
    procs += [mp.Process(target=rotator, args=(path, 15)),
              mp.Process(target=compactor, args=(path, 15)),
              mp.Process(target=compactor, args=(path, 10))]
    rd = mp.Process(target=reader, args=(path, stop, errq))
    rd.start()
    for pr in procs:
        pr.start()
    accepted = []
    for _ in range(n_writers):
        accepted += q.get()
    for pr in procs:
        pr.join()
    stop.set()
    rd.join()

    while not errq.empty():
        print(f"trial {trial_id}: {errq.get()}")
        return False

    final = [(r["w"], r["i"]) for r in recover_metrics(path)]
    ok = True
    if len(final) != len(accepted):
        print(f"trial {trial_id}: count {len(final)} != accepted {len(accepted)}")
        ok = False
    if set(final) != set(accepted):
        missing = set(accepted) - set(final)
        extra = set(final) - set(accepted)
        print(f"trial {trial_id}: missing={list(missing)[:5]} extra={list(extra)[:5]}")
        ok = False
    if len(final) != len(set(final)):
        print(f"trial {trial_id}: duplicates in final set")
        ok = False
    # per-writer subsequence must follow write order
    by_writer = {}
    for w, i in final:
        by_writer.setdefault(w, []).append(i)
    for w, seq in by_writer.items():
        if seq != sorted(seq):
            print(f"trial {trial_id}: writer {w} out of order: {seq[:10]}")
            ok = False
    # no staging leftovers
    files = os.listdir(tmpd)
    if any(f.endswith(".compact") or f.endswith(".tmp") for f in files):
        print(f"trial {trial_id}: leftover staging files: {files}")
        ok = False
    return ok


if __name__ == "__main__":
    mp.set_start_method("fork")
    results = [trial(t) for t in range(8)]
    print("PASSED" if all(results) else "FAILED", sum(results), "/", len(results))
    sys.exit(0 if all(results) else 1)

