from weighted_batcher import append_metrics, compact_metrics, recover_metrics, rotate_metrics


def writer(wid, path, n, outq):
    accepted = []
    for i in range(n):
        try:
            append_metrics(path, '{"w":%d,"i":%d}' % (wid, i))
            accepted.append((wid, i))
        except OSError as e:
            print("append error", e)
        # tiny pause so operations interleave
        if random.random() < 0.02:
            for _ in range(1000):
                pass
    outq.put(accepted)


def rotator(path, stop_after):
    for _ in range(stop_after):
        try:
            rotate_metrics(path)
        except FileNotFoundError:
            # live log can vanish in the rename/recreate window
            pass


def compactor(path, stop_after):
    for _ in range(stop_after):
        try:
            compact_metrics(path)
        except FileNotFoundError:
            pass


def reader(path, stop_event, errors):
    try:
        while not stop_event.is_set():
            seen = []
            for r in recover_metrics(path):
                seen.append((r["w"], r["i"]))
            # no duplicate records in any observed snapshot
            if len(seen) != len(set(seen)):
                errors.put("duplicate in snapshot")
    except (OSError, ValueError) as e:
        errors.put(f"snapshot error: {e!r}")


